import { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { MessageSquare, Send, LifeBuoy, ArrowLeft } from "lucide-react"; // Asumiendo que usas lucide-react
import "./Soporte.css";

export default function Soporte() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    asunto: "",
    mensaje: ""
  });

  const userId = 6; // Este vendría de tu context/auth

  const validar = () => {
    if (!form.asunto || !form.mensaje) {
      alert("Por favor, complete todos los campos obligatorios.");
      return false;
    }
    if (form.mensaje.length < 10) {
      alert("El mensaje debe ser más descriptivo (mínimo 10 caracteres).");
      return false;
    }
    return true;
  };

  const enviarMensaje = async () => {
    if (!validar()) return;
    try {
      await axios.post("http://localhost:3000/api/soporte", {
        ...form,
        id_usuario: userId
      });
      alert("Su mensaje ha sido enviado al equipo de soporte ✅");
      setForm({ asunto: "", mensaje: "" });
    } catch (error) {
      alert("Hubo un error al enviar su consulta. Intente de nuevo.");
    }
  };

  return (
    <div className="soporte-page">
      {/* BOTÓN VOLVER */}
      <button onClick={() => navigate(-1)} className="btn-regresar-premium">
        <ArrowLeft size={16} /> Regresar al Panel
      </button>

      <div className="soporte-header">
        <h1>Centro de Asistencia</h1>
        <p className="subtitulo-premium">Estamos aquí para garantizar su experiencia exclusiva</p>
      </div>

      <div className="soporte-grid">
        {/* LADO IZQUIERDO: INFO DE CONTACTO */}
        <div className="soporte-info-card">
          <div className="info-item">
            <div className="icon-wrapper">
              <LifeBuoy size={24} color="#1f6f54" />
            </div>
            <div>
              <h4>Soporte Especializado</h4>
              <p>Respuesta garantizada en menos de 24 horas hábiles.</p>
            </div>
          </div>
          <div className="info-item">
            <div className="icon-wrapper">
              <MessageSquare size={24} color="#1f6f54" />
            </div>
            <div>
              <h4>Asesoría Directa</h4>
              <p>Consultas sobre piezas específicas o procesos de adquisición.</p>
            </div>
          </div>
        </div>

        {/* LADO DERECHO: FORMULARIO */}
        <div className="soporte-card-main">
          <div className="accent-line"></div>
          <div className="card-body">
            <h3>Enviar una Consulta</h3>
            
            <div className="input-group-premium">
              <label className="label-min">ASUNTO DE LA CONSULTA</label>
              <input
                type="text"
                placeholder="Ej. Información sobre envío de esmeralda"
                value={form.asunto}
                onChange={(e) => setForm({ ...form, asunto: e.target.value })}
              />
            </div>

            <div className="input-group-premium">
              <label className="label-min">DETALLE DE SU MENSAJE</label>
              <textarea
                placeholder="Describa su inquietud detalladamente..."
                value={form.mensaje}
                onChange={(e) => setForm({ ...form, mensaje: e.target.value })}
              />
            </div>

            <button className="btn-enviar-premium" onClick={enviarMensaje}>
              <Send size={18} />
              <span>ENVIAR CONSULTA</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
